package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"github.com/vi-latyshev/go-cluster-backup/tools/internal/pluginmeta"
)

// marshalIndent is the one unprovokable failure seam: encoding a fixed struct
// of strings cannot fail, and a test overrides it to prove the error path.
var marshalIndent = json.MarshalIndent

// output is one tracked generated file.
type output struct {
	path string
	data []byte
}

// render discovers the plugins of the module at root and returns the tracked
// files: the composition root, its hostless half and the Floor manifest.
func render(root string) ([]output, error) {
	module, err := pluginmeta.ModulePath(root)
	if err != nil {
		return nil, err
	}
	plugins, err := load(root)
	if err != nil {
		return nil, err
	}
	closure, err := floorClosure(plugins)
	if err != nil {
		return nil, err
	}
	code, err := renderAll(module, plugins)
	if err != nil {
		return nil, err
	}
	components, err := renderComponents(module, plugins)
	if err != nil {
		return nil, err
	}
	manifest, err := renderFloor(plugins, closure)
	if err != nil {
		return nil, err
	}
	return []output{
		{path: filepath.Join(root, filepath.FromSlash(allPath), generatedName), data: code},
		{path: filepath.Join(root, filepath.FromSlash(componentsPath), generatedName), data: components},
		{path: filepath.Join(root, filepath.FromSlash(allPath), floorName), data: manifest},
	}, nil
}

// floorClosure computes the effective floor set the manifest records: every
// plugin whose Spec declares Floor plus, transitively, every effective
// dependency of one. Declared-Floor and promoted dependencies are
// indistinguishable — both are mandatory. The dependency graph is the generated
// production imports united with the literal Spec.Requires; every edge must name
// a compiled plugin, and a cycle or a self-dependency is refused.
func floorClosure(plugins []*plugin) (map[string]bool, error) {
	byID := make(map[string]*plugin, len(plugins))
	for _, p := range plugins {
		byID[p.id] = p
	}
	deps := make(map[string][]string, len(plugins))
	for _, p := range plugins {
		effective := effectiveDependencies(p)
		for _, dep := range effective {
			switch {
			case dep == p.id:
				return nil, fmt.Errorf("plugin %q depends on itself", p.id)
			case byID[dep] == nil:
				return nil, fmt.Errorf("plugin %q depends on unregistered plugin %q", p.id, dep)
			}
		}
		deps[p.id] = effective
	}
	if err := checkCycles(plugins, deps); err != nil {
		return nil, err
	}
	set := make(map[string]bool, len(plugins))
	queue := make([]string, 0, len(plugins))
	for _, p := range plugins {
		if p.floor {
			queue = append(queue, p.id)
		}
	}
	for len(queue) > 0 {
		id := queue[0]
		queue = queue[1:]
		if set[id] {
			continue
		}
		set[id] = true
		queue = append(queue, deps[id]...)
	}
	return set, nil
}

// effectiveDependencies is the generated imports united with the runtime-only
// Requires, imports first, without duplicates — the order the loader uses.
func effectiveDependencies(p *plugin) []string {
	seen := make(map[string]bool, len(p.imports)+len(p.requires))
	out := make([]string, 0, len(p.imports)+len(p.requires))
	for _, dep := range append(append([]string(nil), p.imports...), p.requires...) {
		if seen[dep] {
			continue
		}
		seen[dep] = true
		out = append(out, dep)
	}
	return out
}

// checkCycles refuses a dependency cycle, naming the path that closes it.
func checkCycles(plugins []*plugin, deps map[string][]string) error {
	const (
		unvisited = iota
		visiting
		visited
	)
	color := make(map[string]int, len(plugins))
	var visit func(id string, path []string) error
	visit = func(id string, path []string) error {
		switch color[id] {
		case visiting:
			return fmt.Errorf("dependency cycle: %s", strings.Join(append(path, id), " -> "))
		case visited:
			return nil
		}
		color[id] = visiting
		for _, dep := range deps[id] {
			if err := visit(dep, append(append([]string(nil), path...), id)); err != nil {
				return err
			}
		}
		color[id] = visited
		return nil
	}
	for _, p := range plugins {
		if err := visit(p.id, nil); err != nil {
			return err
		}
	}
	return nil
}

// renderAll writes the composition root: Register over a fresh factory registry
// and Compose over a caller's, both the hostless half plus every process host.
func renderAll(module string, plugins []*plugin) ([]byte, error) {
	ordered := sortPlugins(plugins)
	var hosts []*plugin
	for _, p := range ordered {
		if isHost(p) {
			hosts = append(hosts, p)
		}
	}
	componentsImport := module + "/" + componentsPath
	reserved := map[string]bool{"loader": true, "instances": true, "components": true}
	if err := checkNames(hosts, reserved); err != nil {
		return nil, err
	}

	var b bytes.Buffer
	b.WriteString("// Code generated by tools/gen; DO NOT EDIT.\n\n")
	b.WriteString("// Package all is the compiled distribution's composition root: one Register\n")
	b.WriteString("// call installs every plugin of this repository over a fresh factory registry,\n")
	b.WriteString("// and one Compose call installs them over a registry the caller owns. It is not\n")
	b.WriteString("// a plugin itself.\n")
	b.WriteString("package all\n\n")
	imports := []string{module + "/internal/loader", module + "/internal/plugins/instances", componentsImport}
	for _, p := range hosts {
		imports = append(imports, p.path)
	}
	writeImports(&b, imports)
	b.WriteString("// Register installs every compiled plugin — the process hosts included — over\n")
	b.WriteString("// one fresh factory registry.\n")
	b.WriteString("func Register(r *loader.Registry) error {\n")
	b.WriteString("\treturn Compose(r, instances.NewRegistry())\n")
	b.WriteString("}\n\n")
	b.WriteString("// Compose installs every compiled plugin over a factory registry the caller\n")
	b.WriteString("// owns: the hostless half first, then each host's Apply.\n")
	b.WriteString("func Compose(r *loader.Registry, factories *instances.Registry) error {\n")
	b.WriteString("\tif err := components.Compose(r, factories); err != nil {\n")
	b.WriteString("\t\treturn err\n")
	b.WriteString("\t}\n")
	writeAdds(&b, hosts)
	b.WriteString("\treturn nil\n}\n")
	return b.Bytes(), nil
}

// renderComponents writes the hostless half: every compiled plugin except the
// process hosts, over one Compose call. It imports no host, so a host's own
// white-box tests can build the graph without an import cycle.
func renderComponents(module string, plugins []*plugin) ([]byte, error) {
	ordered := sortPlugins(plugins)
	components := make([]*plugin, 0, len(ordered))
	for _, p := range ordered {
		if !isHost(p) {
			components = append(components, p)
		}
	}
	instancesImport := module + "/internal/plugins/instances"
	// The registry package is a library plugin like any other; this file already
	// imports it, so its own name is the one exception to the reserved set.
	names := make(map[string]string, len(components))
	for _, p := range components {
		if !importableFrom(module+"/"+componentsPath, p.path) {
			return nil, fmt.Errorf("plugin %s is inside a Go internal boundary", p.path)
		}
		if p.path == instancesImport {
			continue
		}
		if p.name == "loader" || p.name == "instances" {
			return nil, fmt.Errorf("plugin %s uses the reserved package name %q", p.path, p.name)
		}
		if other, duplicate := names[p.name]; duplicate {
			return nil, fmt.Errorf("plugins %s and %s share the package name %q", other, p.path, p.name)
		}
		names[p.name] = p.path
	}

	var b bytes.Buffer
	b.WriteString("// Code generated by tools/gen; DO NOT EDIT.\n\n")
	b.WriteString("// Package components is the compiled distribution without its process hosts:\n")
	b.WriteString("// every provider, workflow and library plugin in one Compose call. It imports\n")
	b.WriteString("// no host, so a host's own white-box tests build this half and add the host\n")
	b.WriteString("// themselves.\n")
	b.WriteString("package components\n\n")
	imports := []string{module + "/internal/loader", instancesImport}
	seen := map[string]bool{module + "/internal/loader": true, instancesImport: true}
	for _, p := range components {
		if seen[p.path] {
			continue
		}
		seen[p.path] = true
		imports = append(imports, p.path)
	}
	writeImports(&b, imports)
	b.WriteString("// Compose installs every compiled non-host plugin: the generated import graph,\n")
	b.WriteString("// then one loader.Add per plugin. A factory backend also contributes to\n")
	b.WriteString("// factories.\n")
	b.WriteString("func Compose(r *loader.Registry, factories *instances.Registry) error {\n")
	renderImports(&b, ordered)
	writeAdds(&b, components)
	b.WriteString("\treturn nil\n}\n")
	return b.Bytes(), nil
}

// sortPlugins orders the plugin set by import path, the stable order every
// generated file lists.
func sortPlugins(plugins []*plugin) []*plugin {
	ordered := append([]*plugin(nil), plugins...)
	sort.Slice(ordered, func(i, j int) bool { return ordered[i].path < ordered[j].path })
	return ordered
}

// checkNames proves one generated file can reference every package: the
// reserved names are the imports the file writes itself, and two plugins named
// alike cannot both be imported.
func checkNames(plugins []*plugin, reserved map[string]bool) error {
	names := make(map[string]string, len(plugins))
	for _, p := range plugins {
		if reserved[p.name] {
			return fmt.Errorf("plugin %s uses the reserved package name %q", p.path, p.name)
		}
		if other, duplicate := names[p.name]; duplicate {
			return fmt.Errorf("plugins %s and %s share the package name %q", other, p.path, p.name)
		}
		names[p.name] = p.path
	}
	return nil
}

// writeImports writes a sorted, deduplicated import block.
func writeImports(b *bytes.Buffer, paths []string) {
	seen := make(map[string]bool, len(paths))
	sorted := make([]string, 0, len(paths))
	for _, path := range paths {
		if seen[path] {
			continue
		}
		seen[path] = true
		sorted = append(sorted, path)
	}
	sort.Strings(sorted)
	b.WriteString("import (\n")
	for _, path := range sorted {
		fmt.Fprintf(b, "\t%q\n", path)
	}
	b.WriteString(")\n\n")
}

// writeAdds writes the one registration table and its loop.
func writeAdds(b *bytes.Buffer, plugins []*plugin) {
	b.WriteString("\tadds := []struct {\n")
	b.WriteString("\t\tspec  loader.Spec\n")
	b.WriteString("\t\tapply func(*loader.Registry) error\n")
	b.WriteString("\t}{\n")
	for _, p := range plugins {
		switch p.apply {
		case applyNone:
			fmt.Fprintf(b, "\t\t{%s.Spec, nil},\n", p.name)
		case applyFactory:
			fmt.Fprintf(b, "\t\t{%s.Spec, func(lr *loader.Registry) error { return %s.Apply(lr, factories) }},\n", p.name, p.name)
		default:
			fmt.Fprintf(b, "\t\t{%s.Spec, %s.Apply},\n", p.name, p.name)
		}
	}
	b.WriteString("\t}\n")
	b.WriteString("\tfor _, add := range adds {\n")
	b.WriteString("\t\tif err := loader.Add(r, add.spec, add.apply); err != nil {\n")
	b.WriteString("\t\t\treturn err\n")
	b.WriteString("\t\t}\n")
	b.WriteString("\t}\n")
}

// importableFrom reports whether the Go internal rule lets importer import
// target: every "internal" path element allows only packages rooted at its
// parent directory. The topology is legal when the composition root sits under
// each boundary.
func importableFrom(importer, target string) bool {
	elements := strings.Split(target, "/")
	for i, element := range elements {
		if i == 0 || element != "internal" {
			continue
		}
		boundary := strings.Join(elements[:i], "/")
		if importer != boundary && !strings.HasPrefix(importer, boundary+"/") {
			return false
		}
	}
	return true
}

// renderImports writes the generated import graph. An empty graph is a valid
// distribution of plugins that import no other plugin.
func renderImports(b *bytes.Buffer, plugins []*plugin) {
	deps := make([]*plugin, 0, len(plugins))
	for _, p := range plugins {
		if len(p.imports) > 0 {
			deps = append(deps, p)
		}
	}
	if len(deps) == 0 {
		b.WriteString("\tif err := loader.SetImports(r, loader.Imports{}); err != nil {\n\t\treturn err\n\t}\n")
		return
	}
	width := 0
	keys := make([]string, len(deps))
	for i, p := range deps {
		keys[i] = fmt.Sprintf("%q:", p.id)
		width = max(width, len(keys[i]))
	}
	b.WriteString("\tif err := loader.SetImports(r, loader.Imports{\n")
	for i, p := range deps {
		fmt.Fprintf(b, "\t\t%s%s {", keys[i], strings.Repeat(" ", width-len(keys[i])))
		for j, dep := range p.imports {
			if j > 0 {
				b.WriteString(", ")
			}
			fmt.Fprintf(b, "%q", dep)
		}
		b.WriteString("},\n")
	}
	b.WriteString("\t}); err != nil {\n\t\treturn err\n\t}\n")
}

// floorPlugin is one manifest row: the compiled identity and dependency facts a
// reviewer or a rule can check without decoding the generated Go.
type floorPlugin struct {
	ID       string   `json:"id"`
	Factory  bool     `json:"factory"`
	Floor    bool     `json:"floor"`
	Imports  []string `json:"imports,omitempty"`
	Requires []string `json:"requires,omitempty"`
	After    []string `json:"after,omitempty"`
}

// renderFloor writes the tracked manifest, one row per plugin sorted by id and
// the effective floor set the closure computed.
func renderFloor(plugins []*plugin, closure map[string]bool) ([]byte, error) {
	rows := make([]floorPlugin, 0, len(plugins))
	for _, p := range plugins {
		rows = append(rows, floorPlugin{
			ID:       p.id,
			Factory:  p.apply == applyFactory,
			Floor:    closure[p.id],
			Imports:  p.imports,
			Requires: p.requires,
			After:    p.after,
		})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].ID < rows[j].ID })
	data, err := marshalIndent(struct {
		Plugins []floorPlugin `json:"plugins"`
	}{Plugins: rows}, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("encode floor manifest: %w", err)
	}
	return append(data, '\n'), nil
}
